const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const newDelhi = ee.Geometry.Point([77.2090, 28.6139]);
  const modinagar = ee.Geometry.Point([77.5833, 28.8333]);
  const greaterNoida = ee.Geometry.Point([77.5340, 28.4744]);

  const surroundingRegion = ee.Geometry.Polygon([
    [77.4, 28.4], [77.7, 28.4], [77.7, 28.9], [77.4, 28.9], [77.4, 28.4]
  ]);

  const newDelhiRegion = ee.Geometry.Point([77.2090, 28.6139]).buffer(10000);

  const startDate = '2014-01-30';
  const endDate = '2014-01-31';

  // 2. Data Acquisition - Try MODIS Terra Daily Surface Reflectance
  let collection = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(startDate, endDate)
    .filterBounds(newDelhi);

  const size = collection.size().getInfo();
  console.log('MODIS images found:', size);

  if (size === 0) {
    // Try Landsat 8
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_TOA')
      .filterDate(startDate, endDate)
      .filterBounds(newDelhi);

    const landsatSize = collection.size().getInfo();
    console.log('Landsat 8 images found:', landsatSize);

    if (landsatSize === 0) {
      console.log('No data available for January 30, 2014');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  const image = collection.first();

  // 3. Fog detection using visible and NIR bands
  // For MODIS: use state_1km band which contains cloud mask info
  const cloudMask = image.select('state_1km');

  // Bit 0-1: cloud state (00=clear, 01=cloudy, 10=mixed, 11=not set)
  // Bit 10: internal cloud algorithm flag
  const cloudBit = cloudMask.bitwiseAnd(3); // Get bits 0-1

  // Consider cloudy pixels as potential fog (low-level clouds in winter)
  const fogMask = cloudBit.gte(1);

  // 4. Calculate fog coverage for New Delhi
  const newDelhiStats = fogMask.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newDelhiRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const newDelhiFog = newDelhiStats.get('state_1km').getInfo();

  const newDelhiCount = fogMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: newDelhiRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('state_1km').getInfo();

  console.log('New Delhi valid pixels:', newDelhiCount);

  if (newDelhiCount === 0) {
    console.log('No valid pixels in New Delhi region');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate fog coverage for surrounding areas
  const surroundingStats = fogMask.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: surroundingRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const surroundingFog = surroundingStats.get('state_1km').getInfo();

  const surroundingCount = fogMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: surroundingRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('state_1km').getInfo();

  console.log('Surrounding area valid pixels:', surroundingCount);

  if (surroundingCount === 0) {
    console.log('No valid pixels in surrounding region');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Validation & Final Answer
  if (newDelhiFog === null || surroundingFog === null) {
    console.log('Calculation failed - null values');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log('New Delhi fog coverage:', (newDelhiFog * 100).toFixed(2) + '%');
  console.log('Surrounding fog coverage:', (surroundingFog * 100).toFixed(2) + '%');

  if (newDelhiFog < surroundingFog) {
    console.log('New Delhi shows LESS fog than surrounding areas');
    console.log('<answer>A</answer>');
  } else {
    console.log('New Delhi does NOT show less fog than surrounding areas');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
